# Step 3.
# Generate (extraction output with wrong format, with correct format) datasets.
# 
# Randomly insert errors (e.g., corrupting delimiters, removing fields) into correct outputs
# to construct incorrectly formatted extraction outputs for finetuning on format directly.
# 
# Depend on the datasets generated by `generate_long_text_entites_dataset.py`.
# Currently using the 200-token length datasets.

import json
import random
import re


TUPLE_DELIMITER = "<|#|>"
COMPLETE_DELIMITER = "<|COMPLETE|>"
MALFORMED_DELIMITERS = [".", ",", " ", "<#>", "<|#", "|#>", "<|", "|>", "<||>", "<||>"]

def corrupt_delimiter(line):
    # Replace one delimiter in the line with a malformed one
    matches = [m.start() for m in re.finditer(re.escape(TUPLE_DELIMITER), line)]
    if not matches:
        return line
    idx = random.choice(matches)
    malformed = random.choice(MALFORMED_DELIMITERS)
    return line[:idx] + malformed + line[idx+len(TUPLE_DELIMITER):]

def remove_fields(line):
    # Remove 1-2 fields and delimiters from a random entity/relation line
    fields = line.split(TUPLE_DELIMITER)
    if len(fields) <= 2:
        return line  # nothing to remove
    n_remove = random.choice([1, 2])
    if len(fields) - n_remove < 2:
        n_remove = 1
    idxs = random.sample(range(1, len(fields)), n_remove)  # don't remove the type field
    new_fields = [f for i, f in enumerate(fields) if i not in idxs]
    return TUPLE_DELIMITER.join(new_fields)

def corrupt_response(gt_response):
    lines = gt_response.strip().split("\n")
    # Remove trailing COMPLETE delimiter for easier manipulation
    has_complete = False
    if lines and lines[-1].strip() == COMPLETE_DELIMITER:
        has_complete = True
        lines = lines[:-1]

    # Decide how many corruptions to apply
    n_corruptions = random.randint(10, 20)
    
    # Currently not removing COMPLETE_DELIMITER
    #corruption_types = [1, 2, 3]
    corruption_types = [1, 2]

    # For each corruption, pick a type and apply
    for _ in range(n_corruptions):
        ctype = random.choice(corruption_types)
        # Pick a random line to corrupt (entity/relation only)
        entity_relation_idxs = [i for i, l in enumerate(lines) if l.startswith("entity") or l.startswith("relation")]
        if not entity_relation_idxs:
            continue
        idx = random.choice(entity_relation_idxs)
        if ctype == 1:
            lines[idx] = remove_fields(lines[idx])
        elif ctype == 2:
            lines[idx] = corrupt_delimiter(lines[idx])
        #elif ctype == 3:
        #    has_complete = False  # Remove COMPLETE_DELIMITER

    corrupted_text = "\n".join(lines)
    if has_complete:
        corrupted_text = corrupted_text.rstrip() + "\n" + COMPLETE_DELIMITER
    return corrupted_text.strip()

def main():
    filenames = [
        "./long_text_dataset/text_to_correct_200_train.json"
    ]
    outputs = [
        "./incorrect_correct_dataset/format_error_pairs_200_train.json"
    ]
    for filename, output_file in zip(filenames, outputs):
        with open(filename, "r", encoding="utf-8") as f:
            data = json.load(f)
        out = []
        for i in range(2):
            for ex in data:
                gt = ex["response"]
                wrong = corrupt_response(gt)
                out.append({"wrong_response": wrong, "ground_truth_response": gt})
        with open(output_file, "w", encoding="utf-8") as f:
            json.dump(out, f, indent=2, ensure_ascii=False)
        print(f"Wrote {len(out)} pairs to {output_file}")

if __name__ == "__main__":
    main()
